import { DatabaseSync } from 'node:sqlite';

// abre (ou cria) o arquivo do banco
const db = new DatabaseSync('tarefas.db');

// 1. cria a tabela se ela ainda não existir
db.exec(`CREATE TABLE IF NOT EXISTS tarefas (
  id INTEGER PRIMARY KEY,
  nome TEXT NOT NULL,
  feito INTEGER DEFAULT 0
)`);

// 2. prepara os comandos uma vez
const inserir = db.prepare('INSERT INTO tarefas (nome) VALUES (?)');
const listar = db.prepare('SELECT * FROM tarefas');

// 3. executa: cada ? recebe um valor na ordem
inserir.run('estudar Node');
inserir.run('fazer exercício');

// SELECT devolve um array de objetos
console.log(listar.all());
// [ { id: 1, nome: 'estudar Node', feito: 0 },
//   { id: 2, nome: 'fazer exercício', feito: 0 } ]

import { DatabaseSync } from 'node:sqlite';

const db = new DatabaseSync('tarefas.db');

// tabela criada na primeira execução; nas seguintes, IF NOT EXISTS ignora
db.exec(`CREATE TABLE IF NOT EXISTS tarefas (
  id INTEGER PRIMARY KEY,
  nome TEXT NOT NULL,
  feito INTEGER DEFAULT 0
)`);

// comandos preparados UMA vez, reutilizados várias vezes
const inserir = db.prepare('INSERT INTO tarefas (nome, feito) VALUES (?, ?)');
const porId = db.prepare('SELECT * FROM tarefas WHERE id = ?');
const pendentes = db.prepare('SELECT * FROM tarefas WHERE feito = 0');

// INSERT com espaço reservado: cada ? recebe um valor na ordem
inserir.run('estudar Node', 0);
inserir.run('fazer exercício', 1);

// WHERE id = ? devolve a linha certa — ou undefined se não existir
console.log(porId.get(1)); // { id: 1, nome: 'estudar Node', feito: 0 }

// WHERE feito = 0 devolve só as pendentes (uma linha)
console.log(pendentes.all());
// [ { id: 1, nome: 'estudar Node', feito: 0 } ]
